const tabId = 248688717;

const elementsDetail = await browserjs(tabId, () => {
  const modal = document.querySelector('#modal');
  if (!modal) return null;

  // Find all elements containing Hunting, Auction, Mineral Rights
  const targets = ['Hunting', 'Auction', 'Mineral Rights'];
  const results = [];

  for (const t of targets) {
    const all = Array.from(modal.querySelectorAll('*')).filter(el => {
      // Check direct text or leaf text
      return Array.from(el.childNodes).some(child => child.nodeType === Node.TEXT_NODE && child.textContent.includes(t));
    });
    results.push({
      target: t,
      matches: all.map(el => ({
        tag: el.tagName,
        className: el.className,
        id: el.id,
        parentTag: el.parentElement?.tagName,
        parentClass: el.parentElement?.className,
        outerHTML: el.outerHTML.slice(0, 200)
      }))
    });
  }

  return results;
});

console.log("Details for targets:", JSON.stringify(elementsDetail, null, 2));

