const tabId = 248688717;

const cardsData = await browserjs(tabId, () => {
  // Find all cards or listing blocks
  const links = Array.from(document.querySelectorAll('a[href*="/pid/"]'));
  // Let's group by URL
  const byUrl = {};
  for (const a of links) {
    const url = a.href;
    if (!byUrl[url]) {
      // Find enclosing container
      let container = a;
      for (let i = 0; i < 5; i++) {
        if (container.parentElement && container.parentElement.innerText.length > container.innerText.length + 50) {
          container = container.parentElement;
        }
      }
      byUrl[url] = container.innerText.trim();
    }
  }
  return byUrl;
});

