const tabId = 248688717;

const urls = [
  "https://www.landwatch.com/lane-county-kansas-farms-and-ranches-for-sale/pid/428216570",
  "https://www.landwatch.com/rawlins-county-kansas-farms-and-ranches-for-sale/pid/428215724",
  "https://www.landwatch.com/pawnee-county-kansas-farms-and-ranches-for-sale/pid/428205477"
];

const results = [];

for (const url of urls) {
  await tool.navigate({ tabId, url });
  await tool.wait_for({ tabId, condition: "load_state", value: "load", timeout_ms: 15000 });

  // Click "Read More" if present
  await browserjs(tabId, () => {
    const readMore = Array.from(document.querySelectorAll('button, a')).find(el => el.textContent?.trim() === 'Read More');
    if (readMore) readMore.click();
    const showMore = Array.from(document.querySelectorAll('button, a')).find(el => el.textContent?.trim().includes('Show More Features'));
    if (showMore) showMore.click();
  });
  await tool.wait_for({ tabId, condition: "dom_settled", timeout_ms: 1000 });

  const data = await browserjs(tabId, (u) => {
    const text = document.body.innerText;
    const h1 = document.querySelector('h1')?.innerText;
    const title = document.title;

    // Find mentions of mineral
    const mineralMatches = [];
    const minReg = /.{0,60}mineral.{0,60}/gi;
    let m;
    while ((m = minReg.exec(text)) !== null) {
      mineralMatches.push(m[0].replace(/\s+/g, ' '));
    }

    // Find mentions of hunt
    const huntMatches = [];
    const huntReg = /.{0,60}hunt.{0,60}/gi;
    let h;
    while ((h = huntReg.exec(text)) !== null) {
      huntMatches.push(h[0].replace(/\s+/g, ' '));
    }

    // Type / categories
    const type = document.querySelector('[data-testid="listing-type"], .type')?.innerText;

    return {
      url: u,
      title,
      h1,
      mineralMatches,
      huntMatches,
      textSnippet: text.slice(0, 1500)
    };
  }, url);

  results.push(data);
}

console.log("Results for 3 listings:");
for (const r of results) {
  console.log("====================================");
  console.log("URL:", r.url);
  console.log("H1:", r.h1);
  console.log("Mineral matches:", r.mineralMatches);
  console.log("Hunt matches:", r.huntMatches);
}

