const tabId = 248688717;

// Let's check pid/428215724 (880 Acres Rawlins County) and pid/428205477 (156 Acres Pawnee County)
const checkUrls = [
  "https://www.landwatch.com/rawlins-county-kansas-farms-and-ranches-for-sale/pid/428215724",
  "https://www.landwatch.com/pawnee-county-kansas-farms-and-ranches-for-sale/pid/428205477"
];

const details = [];

for (const url of checkUrls) {
  await tool.navigate({ tabId, url });
  await tool.wait_for({ tabId, condition: "load_state", value: "load", timeout_ms: 15000 });

  const info = await browserjs(tabId, () => {
    const scripts = Array.from(document.querySelectorAll('script[type="application/ld+json"]')).map(s => {
      try { return JSON.parse(s.innerText); } catch(e) { return s.innerText; }
    });
    return {
      title: document.title,
      h1: document.querySelector('h1')?.innerText,
      bodyTextSnippet: document.body.innerText.slice(0, 1500),
      scripts
    };
  });
  details.push({ url, info });
}

console.log("Details for Rawlins and Pawnee listings:");
for (const d of details) {
  console.log("-----------------------------------------");
  console.log("URL:", d.url);
  console.log("Title:", d.info.title);
  console.log("H1:", d.info.h1);
  console.log("JSON-LD:", JSON.stringify(d.info.scripts, null, 2));
}

