const tabId = 248688717;

const remainingUrls = [
  "https://www.landwatch.com/rush-county-kansas-farms-and-ranches-for-sale/pid/428081331",
  "https://www.landwatch.com/pawnee-county-kansas-farms-and-ranches-for-sale/pid/427951088",
  "https://www.landwatch.com/wichita-county-kansas-farms-and-ranches-for-sale/pid/428049042",
  "https://www.landwatch.com/rooks-county-kansas-farms-and-ranches-for-sale/pid/427983902",
  "https://www.landwatch.com/pawnee-county-kansas-farms-and-ranches-for-sale/pid/427972991",
  "https://www.landwatch.com/thomas-county-kansas-farms-and-ranches-for-sale/pid/428137809"
];

const results = [];

for (const url of remainingUrls) {
  await tool.navigate({ tabId, url });
  await tool.wait_for({ tabId, condition: "load_state", value: "load", timeout_ms: 15000 });

  const data = await browserjs(tabId, (u) => {
    const text = document.body.innerText;
    const h1 = document.querySelector('h1')?.innerText;
    const title = document.title;
    const size = text.match(/Size:\s*([^\n]+)/i)?.[1] || text.match(/([0-9,.]+)\s*Acres/i)?.[0];
    const lastUpdated = text.match(/Listing last updated:[^\n]+/i)?.[0];

    const scripts = Array.from(document.querySelectorAll('script[type="application/ld+json"]')).map(s => {
      try { return JSON.parse(s.innerText); } catch(e) { return s.innerText; }
    });

    // Find RealEstateListing
    const reListing = scripts.find(s => s['@type'] === 'RealEstateListing');
    const datePosted = reListing?.datePosted;

    // Minerals
    const mineralMatches = [];
    const minReg = /.{0,60}mineral.{0,60}/gi;
    let m;
    while ((m = minReg.exec(text)) !== null) {
      mineralMatches.push(m[0].replace(/\s+/g, ' '));
    }

    // Hunting
    const huntMatches = [];
    const huntReg = /.{0,60}hunt.{0,60}/gi;
    let h;
    while ((h = huntReg.exec(text)) !== null) {
      huntMatches.push(h[0].replace(/\s+/g, ' '));
    }

    return {
      url: u,
      h1,
      size,
      datePosted,
      lastUpdated,
      hasMineral: mineralMatches.length > 0,
      mineralMatches,
      hasHunt: huntMatches.length > 0,
      huntMatches
    };
  }, url);

  results.push(data);
}

console.log("Results for remaining 6 auctions:");
for (const r of results) {
  console.log("-----------------------------------------");
  console.log("URL:", r.url);
  console.log("H1:", r.h1);
  console.log("Size:", r.size);
  console.log("Date Posted:", r.datePosted);
  console.log("Last Updated:", r.lastUpdated);
  console.log("Has Mineral:", r.hasMineral);
  if (r.hasMineral) console.log("Mineral:", r.mineralMatches);
  console.log("Has Hunt:", r.hasHunt);
  if (r.hasHunt) console.log("Hunt:", r.huntMatches);
}

